using System;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using Mori;

namespace MoriDesk {
 internal static class CustomizationTests {
  internal static void Run(string root,Action<bool,string> check){
   Directory.CreateDirectory(root);string path=Path.Combine(root,"settings.json");var defaults=new Settings();
   check(defaults.ThemeAccent=="purple"&&defaults.CloseToTray&&defaults.BookmarkOpenInApp&&defaults.AnimateImages&&defaults.MediaAutoPlay&&defaults.MediaLoop,"new optional customization preserves established behavior by default");
   check(defaults.MediaVolume==70&&!defaults.MediaMuted&&!defaults.ConfirmTrash&&defaults.PreviewBackdrop=="automatic"&&defaults.CanvasCacheMB==48&&defaults.CanvasSaveDelay==1200&&!defaults.CanvasDefaultTopmost,"new settings have lightweight safe defaults");
   File.WriteAllText(path,new JavaScriptSerializer().Serialize(new{LibraryPath=root,Theme="light"}));var old=Settings.LoadFrom(path);check(old.LibraryPath==root&&old.Theme=="light"&&old.CloseToTray&&old.MediaVolume==70&&old.CanvasCacheMB==48,"old settings without optional keys retain library and behavior");
   var custom=new Settings{LibraryPath=root,ThemeAccent="teal",CloseToTray=false,ConfirmTrash=true,BookmarkOpenInApp=false,AnimateImages=false,PreviewBackdrop="dark-checker",MediaVolume=25,MediaMuted=true,MediaAutoPlay=false,MediaLoop=false,CanvasDefaultTopmost=true,CanvasSaveDelay=3000,CanvasCacheMB=32};custom.SaveTo(path);var loaded=Settings.LoadFrom(path);
   check(loaded.ThemeAccent=="teal"&&!loaded.CloseToTray&&loaded.ConfirmTrash&&!loaded.BookmarkOpenInApp&&!loaded.AnimateImages&&loaded.PreviewBackdrop=="dark-checker","appearance and workflow preferences persist independently");check(loaded.MediaVolume==25&&loaded.MediaMuted&&!loaded.MediaAutoPlay&&!loaded.MediaLoop&&loaded.CanvasDefaultTopmost&&loaded.CanvasSaveDelay==3000&&loaded.CanvasCacheMB==32,"all media and canvas preferences round-trip");
   loaded.MediaVolume=-100;loaded.CanvasCacheMB=5000;loaded.CanvasSaveDelay=-10;loaded.ThemeAccent="invalid";loaded.PreviewBackdrop="invalid";check(loaded.MediaVolume==0&&loaded.CanvasCacheMB==128&&loaded.CanvasSaveDelay==500&&loaded.ThemeAccent=="purple"&&loaded.PreviewBackdrop=="automatic","invalid customization values normalize to safe bounds and supported modes");
   File.WriteAllText(path,new JavaScriptSerializer().Serialize(new{LibraryPath=root,CloseToTray="no",MediaVolume="oops",CanvasCacheMB=3,CanvasSaveDelay=900000,ThemeAccent=new[]{"bad"},PreviewBackdrop=123}));loaded=Settings.LoadFrom(path);check(loaded.CloseToTray&&loaded.MediaVolume==70&&loaded.CanvasCacheMB==16&&loaded.CanvasSaveDelay==10000&&loaded.ThemeAccent=="purple"&&loaded.PreviewBackdrop=="automatic","malformed optional keys do not corrupt the valid library route");
   new Settings{LibraryPath=root}.SaveTo(path);var stale=Settings.LoadFrom(path);var current=Settings.LoadFrom(path);current.ThemeAccent="blue";current.CanvasCacheMB=80;current.MediaVolume=15;current.LibraryPath=Path.Combine(root,"new-route");current.SaveTo(path);stale.ThumbnailSize=270;stale.SaveTo(path);loaded=Settings.LoadFrom(path);check(loaded.ThemeAccent=="blue"&&loaded.CanvasCacheMB==80&&loaded.MediaVolume==15&&loaded.LibraryPath==current.LibraryPath&&loaded.ThumbnailSize==270,"stale browse writer preserves all newer customization and routing fields");
   var owner=new Window();Theme.Attach(owner,null);
   try{
    int saves=0;var preview=new PreviewSettingsPanel(owner,true,loaded,value=>saves++);preview.Volume.Value=100;preview.AutoPlay.IsChecked=false;check(!preview.SaveDraft()&&saves==0&&!preview.Save.IsEnabled,"preview preference panel cannot persist personal data");
    var draft=new PreviewSettingsPanel(owner,false,Settings.LoadFrom(path),value=>value.SaveTo(path));current=Settings.LoadFrom(path);current.Theme="light";current.ThemeAccent="rose";current.CanvasCacheMB=96;current.SaveTo(path);draft.Volume.Value=35;draft.InternalBrowser.IsChecked=false;check(draft.SaveDraft(),"preview defaults commit without restarting or loading a decoder");loaded=Settings.LoadFrom(path);check(loaded.MediaVolume==35&&!loaded.BookmarkOpenInApp&&loaded.Theme=="light"&&loaded.ThemeAccent=="rose"&&loaded.CanvasCacheMB==96,"preview editor changes only its fields and preserves concurrent theme/canvas edits");
    var canvas=new CanvasSettingsPanel(owner,false,Settings.LoadFrom(path),value=>value.SaveTo(path));canvas.Topmost.IsChecked=true;canvas.SaveDelay.Value=2.5;canvas.Cache.Value=32;check(canvas.SaveDraft(),"canvas preferences save independently");loaded=Settings.LoadFrom(path);check(loaded.CanvasDefaultTopmost&&loaded.CanvasSaveDelay==2500&&loaded.CanvasCacheMB==32&&loaded.MediaVolume==35&&loaded.ThemeAccent=="rose","canvas editor preserves preview and accent preferences");
    var sandbox=new CanvasSettingsPanel(owner,true,loaded,value=>saves++);sandbox.Topmost.IsChecked=false;check(!sandbox.SaveDraft()&&saves==0,"canvas preference preview remains read-only");
    var minimumDelay=new CanvasSettingsPanel(owner,true,new Settings{CanvasSaveDelay=500},value=>saves++);var delayRow=((StackPanel)minimumDelay.Content).Children.OfType<Grid>().First(row=>row.Children.OfType<DockPanel>().Any());var delayText=delayRow.Children.OfType<DockPanel>().Single().Children.OfType<TextBlock>().Single();check(!string.IsNullOrEmpty(delayText.Text)&&delayText.Text.EndsWith(" 秒"),"minimum autosave interval has a visible value even before slider changes");
    int untouchedDelay=0;var untouchedCanvas=new CanvasSettingsPanel(owner,false,new Settings(),value=>untouchedDelay=value.CanvasSaveDelay);check(untouchedCanvas.SaveDelay.Value==1.2&&untouchedCanvas.SaveDraft()&&untouchedDelay==1200,"default 1.2-second autosave is not quantized merely by opening and saving its slider");
    check(System.Windows.Automation.AutomationProperties.GetName(draft.Volume)=="初始音量"&&System.Windows.Automation.AutomationProperties.GetName(canvas.Cache)=="图片预览缓存"&&System.Windows.Automation.AutomationProperties.GetName(canvas.SaveDelay)=="自动保存间隔","actual sliders have accessible names independent of wrapper panels");
    byte[] before=File.ReadAllBytes(path);int failed=0;var bad=new PreviewSettingsPanel(owner,false,Settings.LoadFrom(path),value=>{failed++;throw new IOException("fixture save failure");});bad.Volume.Value=90;bool rejected=false;try{bad.SaveDraft();}catch(IOException){rejected=true;}check(rejected&&failed==1&&File.ReadAllBytes(path).SequenceEqual(before),"failed preview save leaves committed data unchanged");
    foreach(var page in new ScrollViewer[]{draft,canvas}){owner.Content=page;page.Width=476;page.Height=310;page.Measure(new Size(476,310));page.Arrange(new Rect(0,0,476,310));page.UpdateLayout();check(page.ScrollableWidth<.1&&page.ScrollableHeight>0,"compact custom settings have vertical scrolling without horizontal clipping");owner.Content=null;}
   }finally{owner.Content=null;owner.Close();}
   check(MainWindow.ShouldCloseToTray(true,false,new Settings())&&!MainWindow.ShouldCloseToTray(false,false,new Settings())&&!MainWindow.ShouldCloseToTray(true,true,new Settings())&&!MainWindow.ShouldCloseToTray(true,false,new Settings{CloseToTray=false}),"tray preference never blocks explicit exit or relies on a missing tray");
   int reads=0;Func<Settings> failedRead=()=>{reads++;throw new IOException("fixture invalid settings");};check(!MainWindow.ShouldCloseToTray(true,true,failedRead,true)&&!MainWindow.ShouldCloseToTray(false,false,failedRead,true)&&reads==0,"explicit exit and missing tray do not depend on a possibly damaged settings file");check(MainWindow.ShouldCloseToTray(true,false,failedRead,true)&&!MainWindow.ShouldCloseToTray(true,false,failedRead,false)&&reads==2,"normal close falls back to last known tray preference without overwriting damaged settings");
   var concurrent=new Settings{CloseToTray=false,ConfirmTrash=true};SettingsWindow.ApplyGeneralPreferences(concurrent,true,true,false,false);check(!concurrent.CloseToTray&&concurrent.ConfirmTrash,"saving untouched general checkboxes preserves concurrent preference changes");SettingsWindow.ApplyGeneralPreferences(concurrent,true,false,false,true);check(!concurrent.CloseToTray&&concurrent.ConfirmTrash,"explicit general checkbox edits apply to the latest preferences");
  }
 }
}
